import timeit
import statistics
import dask.array as da
import numpy as np
from collections.abc import Mapping
import tlz as toolz # dask dependency, used in HighLevelGraph

# --- Start of HighLevelGraph class definition (copied from pre-edit source and modified for self-containment) ---

# Mock/simplified dask utility functions needed by HighLevelGraph
def ignoring(*exceptions):
    """Context manager to ignore certain exceptions"""
    class Ignore:
        def __enter__(self):
            pass
        def __exit__(self, exc_type, exc_val, exc_tb):
            return exc_type is not None and issubclass(exc_type, exceptions)
    return Ignore()

def is_dask_collection(x):
    """Is x a dask collection? (Simplified for this benchmark)"""
    return hasattr(x, '__dask_graph__') and hasattr(x, '__dask_keys__') and hasattr(x, '__dask_layers__')

def reverse_dict(d):
    """Reverse a dictionary of sets (Simplified for this benchmark)"""
    result = {v: set() for v in toolz.concat(d.values())}
    for k, values in d.items():
        for v in values:
            result[v].add(k)
    return result

class HighLevelGraph(Mapping):
    """ Task graph composed of layers of dependent subgraphs """

    def __init__(self, layers, dependencies):
        self.layers = layers
        self.dependencies = dependencies

    @property
    def dependents(self):
        return reverse_dict(self.dependencies)

    @property
    def dicts(self):
        # Backwards compatibility for now
        return self.layers

    @classmethod
    def _from_collection(cls, name, layer, collection):
        """ `from_collections` optimized for a single collection """
        if is_dask_collection(collection):
            graph = collection.__dask_graph__()
            if isinstance(graph, HighLevelGraph):
                layers = graph.layers.copy()
                layers.update({name: layer})
                deps = graph.dependencies.copy()
                with ignoring(AttributeError):
                    deps.update({name: set(collection.__dask_layers__())})
            else:
                try:
                    [key] = collection.__dask_layers__()
                except AttributeError:
                    key = id(graph)
                layers = {name: layer, key: graph}
                deps = {name: {key}, key: set()}
        else:
            raise TypeError(type(collection))

        return cls(layers, deps)

    @classmethod
    def from_collections(cls, name, layer, dependencies=()):
        """ Construct a HighLevelGraph from a new layer and a set of collections """
        if len(dependencies) == 1:
            return cls._from_collection(name, layer, dependencies[0])
        layers = {name: layer}
        deps = {}
        deps[name] = set()
        for collection in toolz.unique(dependencies, key=id):
            if is_dask_collection(collection):
                graph = collection.__dask_graph__()
                if isinstance(graph, HighLevelGraph):
                    layers.update(graph.layers)
                    deps.update(graph.dependencies)
                    with ignoring(AttributeError):
                        deps[name] |= set(collection.__dask_layers__())
                else:
                    try:
                        [key] = collection.__dask_layers__()
                    except AttributeError:
                        key = id(graph)
                    layers[key] = graph
                    deps[name].add(key)
                    deps[key] = set()
            else:
                raise TypeError(type(collection))

        return cls(layers, deps)

    def __getitem__(self, key):
        for d in self.layers.values():
            if key in d:
                return d[key]
        raise KeyError(key)

    def __len__(self):
        return sum(1 for _ in self)

    def items(self):
        items = []
        seen = set()
        for d in self.layers.values():
            for key in d:
                if key not in seen:
                    seen.add(key)
                    items.append((key, d[key]))
        return items

    def __iter__(self):
        return toolz.unique(toolz.concat(self.layers.values()))

    def keys(self):
        return [key for key, _ in self.items()]

    def values(self):
        return [value for _, value in self.items()]

    @classmethod
    def merge(cls, *graphs):
        layers = {}
        dependencies = {}
        for g in graphs:
            if isinstance(g, HighLevelGraph):
                layers.update(g.layers)
                dependencies.update(g.dependencies)
            elif isinstance(g, Mapping):
                layers[id(g)] = g
                dependencies[id(g)] = set()
            else:
                raise TypeError(g)
        return cls(layers, dependencies)

    def visualize(self, filename="dask.pdf", format=None, **kwargs):
        # Mock this method as it's not relevant for the benchmark
        pass

# --- End of HighLevelGraph class definition ---


# Global variables to be set up once and used by the workload
dask_array_dependency = None
new_layer_name = "my-new-operation"
new_layer_data = None

def setup():
    """
    Prepares a realistic Dask collection to be used as a single dependency
    for HighLevelGraph.from_collections.
    """
    global dask_array_dependency, new_layer_name, new_layer_data

    # Set a random seed for reproducibility
    np.random.seed(42)

    # Create a large NumPy array
    arr = np.random.rand(1000, 1000) # 1 million elements

    # Convert it to a Dask array with multiple chunks
    # This ensures the Dask array has a non-trivial HighLevelGraph structure.
    darr = da.from_array(arr, chunks=(100, 100)) # 10x10 = 100 chunks

    # Perform an operation on the Dask array to create a multi-layer HighLevelGraph.
    # This simulates a real-world Dask collection that has undergone some computation,
    # making the graph merging logic in from_collections more complex.
    dask_array_dependency = darr + 1

    # Define a simple new layer for the HighLevelGraph.
    # The actual content of the tasks within this layer is less important than
    # the structure for the HighLevelGraph construction logic.
    # To make it realistic, we make the new layer depend on a key from the input collection.
    first_dep_key = dask_array_dependency.__dask_keys__()[0]
    new_layer_data = {
        (new_layer_name, 0): (lambda x: x * 2, first_dep_key)
    }

def workload():
    """
    Measures the performance of HighLevelGraph.from_collections when
    constructing a new graph with exactly one Dask collection as a dependency.
    This targets the optimized code path introduced in the diff.
    """
    global dask_array_dependency, new_layer_name, new_layer_data
    _ = HighLevelGraph.from_collections(new_layer_name, new_layer_data, dependencies=[dask_array_dependency])

# Run the benchmark
# number=1: Each call to workload() creates one HighLevelGraph instance.
# repeat=10: Perform 10 repetitions to gather stable statistics.
runtimes = timeit.repeat(workload, number=1, repeat=10, setup=setup)

# Print the mean and standard deviation of the runtimes
print("Mean:", statistics.mean(runtimes))
print("Std Dev:", statistics.stdev(runtimes))
